import process from "node:process";
// Bundles the user-facing Markdown under <repo>/docs/user into a TypeScript
// module so the docs pages never read the filesystem at request time.
//
// Why: the root layout resolves the visitor's language per request, which
// makes every page dynamic, and the `output: "standalone"` production image
// does not contain the repository's docs/ folder. Bundling at build time
// keeps /docs working there (and in `next dev`/`next start` alike).
//
// Only files under docs/user are bundled — that directory is the boundary
// of what may be published; which of them are actually served is decided
// by the allowlist in lib/docs-content.ts.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const docsDir = path.resolve(here, "..", "..", "..", "docs", "user");
const outFile = path.resolve(here, "..", "lib", "docs-bundle.generated.ts");

function walk(dir, base = "") {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const rel = base ? `${base}/${entry.name}` : entry.name;
    if (entry.isDirectory()) return walk(path.join(dir, entry.name), rel);
    return entry.name.endsWith(".md") ? [rel] : [];
  });
}

const files = walk(docsDir).sort();
const body = files
  .map((rel) => `  ${JSON.stringify(rel)}: ${JSON.stringify(fs.readFileSync(path.join(docsDir, rel), "utf8"))},`)
  .join("\n");

const output = `
// AUTO-GENERATED by scripts/generate-docs-bundle.mjs — do not edit, do not commit.
// Source: docs/user/**/*.md (${files.length} files).
export const DOC_FILES: Record<string, string> = {
${body}
};
`;

fs.writeFileSync(outFile, output);
console.log(`docs bundle: ${files.length} file(s) -> ${path.relative(process.cwd(), outFile)}`);
